 CLICK AQUÍ<\\/a><\\/P>\",\"sku\":\"\",\"cantidad\":\"6.7000\",\"precio_unit\":\"11700.00\",\"subtotal\":\"78390.00\",\"es_extra\":\"0\"},{\"id\":\"6087\",\"cotizacion_id\":\"4086\",\"venta_id\":null,\"articulo_id\":\"70\",\"orden\":\"2\",\"titulo\":\"BARRA O ISLA CON PUERTAS\",\"descripcion\":\"NO INCLUYE CUBIERTA.\",\"sku\":\"\",\"cantidad\":\"1.4000\",\"precio_unit\":\"6300.00\",\"subtotal\":\"8820.00\",\"es_extra\":\"0\"}],\"descuento_auto_amt\":0}'),
