(7886, 4466, NULL, 69, 1, 'CLOSET MELAMINA 187', 'MELAMINA BLANCA CON CENTRO MDF 16MM NO TERMITA, NO HUMEDAD, NO RAYADURAS,  <a href=\"https://youtu.be/VBEXVhJJr4E\"> EJEMPLO DE CLOSET STANDARD EN MELAMINA: CLICK AQUÍ</a>\n\nFRENTES, PUERTAS Y UNA TORRE CON HASTA 5 REPISAS FIJAS.\n\nBASE, ZOCLO Y MALETERO (NO INCLUYE FORRADO DE FONDOS EN PAREDES).  \n\nKIT DE HERRAJES, RIELES DE EXTENSION 18\" Y BISAGRAS REFORZADAS, JALADERAS DE NUESTRO CATALOGO, TUBOS Y SOPORTES. \n\nPROFUNDIDAD STANDARD 60 CMS Y ANCHO MAXIMO DE CADA MODULO 60 CMS.  ELEMENTOS ADICIONALES, TORRES, REPISAS, DIVISORES, SE COTIZAN POR SEPARADO. CAMBIOS Y AJUSTES ALTERAN EL PRECIO COTIZADO.  \n\n<a href=\"https://ontimecocinas.com/simuladorclosets/\"> VISITA NUESTRO SIMULADOR: DISEÑA Y VISUALIZA EN TIEMPO REAL EL COLOR DE TU CLOSET - CLICK AQUÍ</a>\n\n<a href=\"https://ontimecocinas.com/catalogomelaminas/\"> CATALOGO DE MELAMINAS STANDARD - CLICK AQUÍ</a>', '', 1.9000, 9800.00, 18620.00, 0),
(7887, 4466, NULL, 70, 2, 'GABINETES EXTRAS', 'EN. MELAMINA STD. GABINETES SUPERIORES SEGUN DISENO (AREA DE TRABE Y AREA DE ANTEPECHO DE PUERTA).\n\nINCLUYE PUERTAS, HERRAJES DE NUESTRO CATALOGO.', '', 3.0000, 3300.00, 9900.00, 0),
(7888, 4471, NULL, 100, 1, 'CLOSET MELAMINA STANDARD 1.6', 'MELAMINA BLANCA CON CENTRO MDF 16MM NO TERMITA, NO HUMEDAD, NO RAYADURAS,  <a href=\"https://youtu.be/VBEXVhJJr4E\"> EJEMPLO DE CLOSET STANDARD EN MELAMINA: CLICK AQUÍ</a>\n\nFRENTES, PUERTAS Y UNA TORRE CON HASTA 5 CAJONES, PUERTA COSMETIQUERA CON REPISA INTERIOR. \n\nBASE, ZOCLO Y MALETERO (NO INCLUYE FORRADO DE FONDOS EN PAREDES).  \n\nKIT DE HERRAJES, RIELES DE EXTENSION 18\" Y BISAGRAS REFORZADAS, JALADERAS DE NUESTRO CATALOGO, TUBOS Y SOPORTES. \n\nPROFUNDIDAD STANDARD 60 CMS Y ANCHO MAXIMO DE CADA MODULO 60 CMS.  ELEMENTOS ADICIONALES, TORRES, REPISAS, DIVISORES, SE COTIZAN POR SEPARADO. CAMBIOS Y AJUSTES ALTERAN EL PRECIO COTIZADO.  \n\n<a href=\"https://ontimecocinas.com/simuladorclosets/\"> VISITA NUESTRO SIMULADOR: DISEÑA Y VISUALIZA EN TIEMPO REAL EL COLOR DE TU CLOSET - CLICK AQUÍ</a>\n\n<a href=\"https://ontimecocinas.com/catalogomelaminas/\"> CATALOGO DE MELAMINAS STANDARD - CLICK AQUÍ</a>', '', 1.9000, 9800.00, 18620.00, 0),
(7889, 4472, NULL, 54, 1, 'CLOSET MELAMINA (SEGUN DISENO) 1.5', 'MELAMINA BLANCA CON CENTRO MDF 16MM NO TERMITA, NO HUMEDAD, NO RAYADURAS,  <a href=\"https://youtu.be/VBEXVhJJr4E\"> EJEMPLO DE CLOSET STANDARD EN MELAMINA: CLICK AQUÍ</a>\n\nFRENTES, PUERTAS Y DOS TORRES DE 2 CAJONES + REPISA INTERIOR Y AREA DE TUBOS.\n\nBASE, ZOCLO Y MALETERO (NO INCLUYE FORRADO DE FONDOS EN PAREDES).  \n\nKIT DE HERRAJES, RIELES DE EXTENSION 18\" Y BISAGRAS REFORZADAS, JALADERAS DE NUESTRO CATALOGO, TUBOS Y SOPORTES. \n\nPROFUNDIDAD STANDARD 60 CMS Y ANCHO MAXIMO DE CADA MODULO 60 CMS.  ELEMENTOS ADICIONALES, TORRES, REPISAS, DIVISORES, SE COTIZAN POR SEPARADO. CAMBIOS Y AJUSTES ALTERAN EL PRECIO COTIZADO.  \n\n<a href=\"https://ontimecocinas.com/simuladorclosets/\"> VISITA NUESTRO SIMULADOR: DISEÑA Y VISUALIZA EN TIEMPO REAL EL COLOR DE TU CLOSET - CLICK AQUÍ</a>\n\n<a href=\"https://ontimecocinas.com/catalogomelaminas/\"> CATALOGO DE MELAMINAS STANDARD - CLICK AQUÍ</a>', '', 1.5000, 12000.00, 18000.00, 0);
