INSERT INTO `empresas` (`id`, `slug`, `nombre`, `logo_url`, `email`, `telefono`, `ciudad`, `moneda`, `impuesto_modo`, `impuesto_pct`, `impuesto_nombre`, `texto_bienvenida`, `texto_aceptar`, `texto_rechazar`, `texto_recibo`, `adc_activo`, `adc_pct`, `adc_horas`, `adc_texto`, `radar_config`, `activa`, `created_at`, `updated_at`, `direccion`, `rfc`, `website`, `dominio_custom`, `notif_email`, `notif_email_acepta`, `notif_email_rechaza`, `notif_config`, `cot_vigencia_dias`, `allow_precio_edit`, `ocultar_cant_pu`, `cot_msg_acepta`, `cot_msg_rechaza`, `cot_terminos`, `cot_footer`, `cot_encabezado`, `cot_theme`, `vta_terminos`, `vta_footer`, `cot_prefijo`, `vta_prefijo`, `plan`, `plan_vence`, `grace_hasta`, `ultima_sync_mp`, `costos_modo`, `auto_suspender_activo`, `auto_suspender_dias`, `descuento_auto_pct_default`, `descuento_auto_dias_default`, `termometro_visible`, `feedback_activo`, `feedback_pregunta`, `feedback_subtitulo`, `feedback_label_comentario`, `feedback_agradecimiento`, `giro`, `onboarding_completo`, `mesa_activa`, `asientos`, `es_trial`, `trial_usado`) VALUES
(2, 'closetfactory', 'Closet Factory Hermosillo', '/uploads/logos/logo_2_1773429109.png', 'info@closetfactory.com.mx', '6624550498', '', 'MXN', 'ninguno', 16.00, 'IVA', NULL, NULL, NULL, NULL, 0, 0.00, 72, NULL, '{\"sensibilidad\":\"medio\",\"modo\":\"medio\",\"calibracion_auto\":true,\"auto_calibrar\":true,\"excluir_internos\":true,\"filtrar_bots\":true,\"deduplicar_30min\":true}', 1, '2026-03-10 13:13:59', '2026-07-18 09:36:31', '', '', 'closetfactory.com.mx', NULL, 'info@ontimecocinas.com', 1, 1, '{\"cotizacion_aceptada\":true,\"cotizacion_rechazada\":true,\"abono_registrado\":true,\"radar_alerta\":true}', 30, 1, 1, 'Gracias por su compra, sera contactado por el asesor', 'Una pena, esperamos verlo pronto', 'CONSULTA NUESTRO CATALOGO DE MELAMINAS AQUI: <a href=\"https://closetfactory.com.mx/melaminas/\"> CATALOGO DE MELAMINAS: CLICK AQUÍ</a>\n-Anticipo 50%.\n-Tiempo de Fabricación 1 a 10 días hábiles (a partir de confirmar el diseño) y 1-2 días de Instalación.\n-Instalamos de Lunes a Viernes en horario de 10am a 6pm.\n-Garantía 2 años contra desperfectos.', 'closetfactory.com.mx', 'Gracias por confiar en nostros, A continuacion presento su cotizacion que nos solicito:', 'azul', '✅Anticipo 50%.\n✅Tiempo de Fabricación 1 a 10 días hábiles (a partir de confirmar el diseño) y 1-2 días de Instalación.\n✅Instalamos de Lunes a Viernes en horario de 10am a 6pm.\n✅Garantía 2 años contra desperfectos.\n\n<p><P />\n<p><P />\nRecibo de Anticipo. Fecha: _______________________\nRECIBI DE ___EL CLIENTE___ LA CANTIDAD DE $______________________________________________________ PESOS M.N. POR CONCEPTO DE ANTICIPO ACORDE A ESTE CONTRATO Y ESPECIFICACIONES DE COTIZACION POR MEDIO DE:\nTRANSFERENCIA ______ EFECTIVO _____ TRANSFERENCIA______.\n\nFIRMA CLOSET FACTORY______________________________________\n<p><P />\n<p><P />\n<p><P />\n\nRecibo Final.  Fecha: _______________________\nRECIBI DE ___EL CLIENTE____ LA CANTIDAD DE $______________________________________________________ PESOS M.N. POR CONCEPTO DE PAGO FINAL ACORDE A ESTE CONTRATO Y ESPECIFICACIONES DE COTIZACION POR MEDIO DE:\nTRANSFERENCIA ______ EFECTIVO _____  POR TRANSFERIR ______.\n\n\n<p>CLOSET FACTORY</p>\n<p></p>\n<p></p>\n<p> 	NOMBRE Y FIRMA DEL CLIENTE</p>', '', 'COT', 'VTA', 'business', '2026-08-17', NULL, '2026-04-18 12:42:02', 'empresa', 0, 30, 0.00, 3, 1, 0, '¿Qué tan satisfecho estás con la atención recibida?', '', 'Cuéntanos brevemente qué podemos mejorar en tu atención', 'Tu opinión nos ayuda a mejorar como te atendemos', 'servicios', 1, 0, NULL, 0, 0),
(4, '_system', 'CotizaCloud Admin', NULL, NULL, NULL, NULL, 'MXN', 'ninguno', 0.00, 'IVA', NULL, NULL, NULL, NULL, 0, 0.00, 72, NULL, NULL, 0, '2026-03-18 18:48:19', '2026-07-23 10:52:49', NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, 30, 1, 0, NULL, NULL, NULL, NULL, NULL, 'verde', NULL, NULL, 'COT', 'VTA', 'business', NULL, NULL, NULL, 'venta', 0, 30, 0.00, 3, 1, 0, '¿Qué tan satisfecho estás con la atención recibida?', '', 'Cuéntanos brevemente qué podemos mejorar en tu atención', 'Tu opinión nos ayuda a mejorar como te atendemos', 'servicios', 1, 0, NULL, 0, 0),
(7, 'granitodepot', 'Granito Depot', '/uploads/logos/logo_7_1774893026.png', 'hola@granitodepot.com', '6621216591', '', 'MXN', 'ninguno', 16.00, 'IVA', NULL, NULL, NULL, NULL, 0, 0.00, 72, NULL, NULL, 1, '2026-03-23 09:41:21', '2026-06-28 09:27:55', '', '', 'granitodepot.com', NULL, 'info@ontimecocinas.com', 1, 1, '{\"cotizacion_aceptada\":true,\"cotizacion_rechazada\":true,\"abono_registrado\":true,\"radar_alerta\":true}', 7, 0, 1, '<strong>&#128336;EL HORARIO DE INSTALACION Y ATENCION ES DE LUNES A VIERNES DE 9AM A 6PM</strong>\n\n<P>&#128204;<a href=\"https://granitodepot.com/simulador/\"> VISITA NUESTRO SIMULADOR: DISEÑA Y VISUALIZA EN TIEMPO REAL EL COLOR DE TU CUBIERTA - CLICK AQUÍ</a></P>\n\n<div style=\"border: 2px solid #5D0202;padding: 5px\">\n&#128073;Condiciones de Pago de Mano de Obra:\nPago 1: 50%  A contratar como Anticipo \nPago 2: 50% Al instalar\nLas Placas deberán ser Liquidadas en su Total para poder Trabajarlas, No garantizamos inventario hasta tener la placa liquidada. Esta politica de pagos aplica para todos los productos.\n</div>\nEL GRANITO/CUARZO SE COTIZA POR M2 y ML. LOS METROS SE CALCULAN AL TENER EL PROYECTO DEFINIDO. *DEBIDO A LA NATURALEZA DEL MATERIAL, PUEDE TENER VARIACION DE COLORES Y PRESENCIA DE MANCHAS, LOS CUALES SON PROPIAS DEL MATERIAL, SIN PODER ALTERAR LA COMPOSICION DE ESTAS MISMAS.\n\nIMPORTANTE: Esta cotización es de caracter informativa, bajo ninguna situación representa una obligación de GRANITO DEPOT para realizar el trabajo, hasta elaborado el pago por el cliente. El Proyecto incluye exclusivamente lo descrito, anexos generan costo. Cotización valida en Transferencia o Efectivo, otro método de pago +3% adicional.\n\n<a href=\"https://granitodepot.com/aviso-de-privacidad/\">CONSULTA AVISO DE PRIVACIDAD</a>\n\n<div style=\"border: 2px solid #5D0202;padding: 5px\">\nConsulta Nuestros Trabajos <a href=\"https://granitodepot.com/blog\"> PORTAFOLIO DE TRABAJOS</a>\n</div>\n\nSomos Granito Depot, Calidad y Experiencia nos respaldan. <a href=\"https://granitodepot.com\">Granito Depot</a> | <a href=\"mailto:hola@granito.com\">hola@granitodepot.com</a> Esta Cotización solo es Válida 7 días, en la dirección y datos proporcionados. ', '', '', '', 'Pongo a su disposición la cotizacion que nos solicito. Nuestras cubiertas se fabrican especialmente sobre pedido, por lo que cada proyecto requiere su tiempo de producción. La programación de fabricación e instalación se asigna conforme se van confirmando y contratando los proyectos.', 'oscuro', 'COMENTARIOS: Nuestros Productos son de origen pre fabricado, pueden presentar variaciones en sus tonalidades y formas. No se aceptan devoluciones. Precios y Disponibilidad pueden variar sin previo aviso.Las Placas deberán ser Liquidadas en su Total para poder Trabajarlas, No garantizamos inventario hasta tener la placa liquidada. En instalaciones el acabado dependera de las texturas del material.\n<P>\nANTICIPO:__________________________________________ RESTA:__________________________________________ FIRMA DE RECIBIDO:_________________________________\n</P>\n<P>\nCuentas para Pagos: HSBC CLABE 021760040676874596 / BANAMEX CLABE 002760701031187924\n</P>', '', 'COT', 'VTA', 'business', '2026-07-28', NULL, NULL, 'venta', 0, 30, 0.00, 3, 0, 0, '¿Qué tan satisfecho estás con la atención recibida?', '', 'Cuéntanos brevemente qué podemos mejorar en tu atención', 'Tu opinión nos ayuda a mejorar como te atendemos', 'servicios', 1, 0, NULL, 0, 0),
(11, 'apple-review', 'Apple Review Demo', NULL, '', '', '', 'MXN', 'ninguno', 16.00, 'IVA', NULL, NULL, NULL, NULL, 0, 0.00, 72, NULL, NULL, 1, '2026-03-29 09:18:37', '2026-07-23 10:52:49', '', '', '', NULL, '', 0, 0, '{\"cotizacion_aceptada\":false,\"cotizacion_rechazada\":false,\"abono_registrado\":true,\"radar_alerta\":true,\"feedback_recibido\":true}', 30, 1, 0, '', '', '', '', '', 'azul', '', '', 'COT', 'VTA', 'business', '2027-07-23', NULL, NULL, 'venta', 0, 30, 0.00, 3, 1, 0, '¿Qué tan satisfecho estás con la atención recibida?', '', 'Cuéntanos brevemente qué podemos mejorar en tu atención', 'Tu opinión nos ayuda a mejorar como te atendemos', 'inmuebles', 1, 0, NULL, 0, 0);
